"""Manuscript content (revision v3). Inline markup: *italic*, **bold**, _{sub}, ^{sup}. Citations: {key} or {k1,k2}."""
import json, re

TITLE = "False-Alarm Control and Explanation Reliability of Feature-Token Transformers for Network Intrusion Detection under Dataset Shift"
AUTHOR = "Xinghui Wu"
AFFIL = "School of Computer Science, University of Birmingham, Birmingham B15 2TT, UK; [e-mail address]"

ABSTRACT = ("Transformer-based network intrusion detection systems (NIDSs) are usually reported at a default decision threshold, on random data splits and with single-run explanations, so their false-alarm behaviour under deployment conditions and the reliability of their explanations remain unclear. "
 "This study evaluates a feature-token Transformer (FTT-IDS) against random forest, XGBoost, MLP, 1D-CNN and FT-Transformer baselines on UNSW-NB15 and TON_IoT under a leakage-controlled, five-seed protocol. "
 "FTT-IDS matches but does not exceed gradient-boosted trees (detection rate at a 1% test false-positive rate: 85.6% versus 86.2% for XGBoost). The decision rule matters more than the model: a threshold fixed at a 1% validation false-alarm budget lowers the UNSW-NB15 test false-positive rate of every model by 18–23 points (from 26.6% to 4.4% for FTT-IDS), yet the budget is still exceeded fourfold because of a train–test shift. "
 "On TON_IoT, where a random split yields F1 above 99.4% and a false-positive rate near 1% for all models, evaluation on unseen source hosts raises the false-positive rate to between 0.5% and 54% depending on the held-out hosts, while validation data continue to indicate 1%. "
 "Recalibrating the threshold on 1000 benign flows from the target network restores the 1% budget on both datasets without attack labels, at a recall of 86% on UNSW-NB15 and of between 7% and 100% on TON_IoT, depending on the held-out hosts. "
 "Expected-gradients SHAP and Integrated Gradients agree on the leading features and are faithful to the trained model, but rankings are only moderately stable across retrained models (Spearman 0.73–0.76), and retraining without the top-ranked features costs little, and less than removing one of two random feature sets. "
 "False-alarm rates at a stated operating point, evaluation on unseen hosts and explanation reliability should be reported alongside accuracy.")
KEYWORDS = "network intrusion detection; Transformer; explainable artificial intelligence; SHAP; false alarms; decision threshold; dataset shift; host-disjoint evaluation; UNSW-NB15; TON_IoT; Internet of Things security"

B = []  # blocks
def h1(t): B.append({"t": "h1", "x": t})
